    pria2: `<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="g2" x1="0" x2="1"><stop stop-color="#6d75ff"/><stop offset="1" stop-color="#d56bff"/></linearGradient></defs><rect width="100" height="100" rx="24" fill="#0d1630"/><circle cx="50" cy="48" r="32" fill="url(#g2)" opacity=".18"/><circle cx="50" cy="40" r="17" fill="#d9a47f"/><path d="M29 76c2-17 14-25 21-25s19 8 21 25" fill="#304052"/><path d="M33 35c6-14 27-22 34-3-3-1-6-1-10-3-8 5-14 7-24 6Z" fill="#131a27"/><circle cx="44" cy="41" r="1.8" fill="#222"/><circle cx="56" cy="41" r="1.8" fill="#222"/><path d="M46 49c3 2 6 2 9 0" stroke="#9b5f5a" stroke-width="2" fill="none" stroke-linecap="round"/></svg>`,
